// Phase 1: 10 hardcoded Doris school URLs.
// Replace slugs with your target schools before running.
return [
  { json: { url: 'https://www.doris.school/schools/united-kingdom/st-edwards-school' } },
  { json: { url: 'https://www.doris.school/schools/united-kingdom/eton-college' } },
  { json: { url: 'https://www.doris.school/schools/united-kingdom/harrow-school' } },
  { json: { url: 'https://www.doris.school/schools/united-kingdom/rugby-school' } },
  { json: { url: 'https://www.doris.school/schools/united-kingdom/winchester-college' } },
  { json: { url: 'https://www.doris.school/schools/united-kingdom/cheltenham-ladies-college' } },
  { json: { url: 'https://www.doris.school/schools/united-kingdom/marlborough-college' } },
  { json: { url: 'https://www.doris.school/schools/united-kingdom/charterhouse' } },
  { json: { url: 'https://www.doris.school/schools/united-kingdom/shrewsbury-school' } },
  { json: { url: 'https://www.doris.school/schools/united-kingdom/tonbridge-school' } }
];

// Supabase returns an array with Prefer: return=representation.
// Normalise to { url, scrape_queue_id } for downstream nodes.
const resp = $input.first().json;
const row = Array.isArray(resp) ? resp[0] : resp;
return [{ json: { url: row.url, scrape_queue_id: row.id } }];

const html = $input.first().json.data;
const { url: sourceUrl, scrape_queue_id: scrapeQueueId } = $('Parse Queue Response').first().json;

if (!html || html.length < 200) {
  return [{ json: { scrape_status: 'failed', error: 'Empty or thin HTML — page may be JS-rendered', source_url: sourceUrl, scrape_queue_id: scrapeQueueId } }];
}

const match = html.match(/<script type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/);
if (!match) {
  return [{ json: { scrape_status: 'failed', error: 'No JSON-LD block found in HTML', source_url: sourceUrl, scrape_queue_id: scrapeQueueId } }];
}

let data;
try {
  data = JSON.parse(match[1]);
} catch (e) {
  return [{ json: { scrape_status: 'failed', error: 'JSON-LD parse error: ' + e.message, source_url: sourceUrl, scrape_queue_id: scrapeQueueId } }];
}

const slug = sourceUrl.split('/').pop();

// sameAs — split into social URLs and official school URL
const sameAs = Array.isArray(data.sameAs) ? data.sameAs : (data.sameAs ? [data.sameAs] : []);
const SOCIAL = ['instagram.com', 'linkedin.com', 'facebook.com', 'twitter.com', 'x.com'];
const instagramUrl = sameAs.find(u => u.includes('instagram.com')) ?? null;
const linkedinUrl  = sameAs.find(u => u.includes('linkedin.com'))  ?? null;
const facebookUrl  = sameAs.find(u => u.includes('facebook.com'))  ?? null;
const officialUrl  = sameAs.find(u => !SOCIAL.some(d => u.includes(d)) && !u.includes('doris.school')) ?? null;

// Curricula: teaches may be a string or array
const curricula = data.teaches
  ? (Array.isArray(data.teaches) ? data.teaches : [data.teaches])
  : [];

// Languages: first entry = instruction medium, rest = subjects offered
const allLangs = Array.isArray(data.knowsLanguage)
  ? data.knowsLanguage
  : (data.knowsLanguage ? [data.knowsLanguage] : []);
const languagesInstruction = allLangs.length > 0 ? [allLangs[0]] : ['English'];
const languagesOffered = allLangs.slice(1);

// Religious affiliation from additionalProperty PropertyValue array
const religiousAffiliation = (data.additionalProperty ?? [])
  .find(p => p.name === 'Religious Affiliation')?.value ?? null;

// Fees: one row per offer object
const fees = (data.offers ?? []).map(o => {
  const name = (o.name ?? '').toLowerCase();
  let feeType = 'additional_fee';
  if (name.includes('tuition') || name.includes('annual') || name.includes('yearly')) {
    feeType = 'yearly_fee';
  } else if (name.includes('application') || name.includes('registration')) {
    feeType = 'application_fee';
  } else if (name.includes('deposit') || name.includes('enrollment') || name.includes('enrolment') || name.includes('acceptance')) {
    feeType = 'enrollment_fee';
  }
  return {
    year_group: o.eligibleCustomerType ?? null,
    fee_type: feeType,
    label: o.name ?? null,
    amount: parseFloat(o.price),
    currency: o.priceCurrency ?? 'GBP',
    notes: o.description ?? null
  };
});

const school = {
  slug,
  name: data.name,
  source_url: sourceUrl,
  official_url: officialUrl,
  founded_year: data.foundingDate ? parseInt(data.foundingDate) : null,
  address_street:  data.address?.streetAddress   ?? null,
  address_city:    data.address?.addressLocality  ?? null,
  address_region:  data.address?.addressRegion    ?? null,
  address_country: data.address?.addressCountry   ?? null,
  address_postcode: data.address?.postalCode      ?? null,
  lat: data.geo?.latitude  ?? null,
  lng: data.geo?.longitude ?? null,
  description: data.description ? data.description.slice(0, 500) : null,
  school_type:           null,
  governance:            null,
  religious_affiliation: religiousAffiliation,
  gender_policy:         null,
  boarding_available:    false,
  day_available:         true,
  student_count: data.numberOfStudents?.value ? parseInt(data.numberOfStudents.value) : null,
  age_min: null,
  age_max: null,
  curricula,
  languages_instruction: languagesInstruction,
  languages_offered:     languagesOffered,
  strengths:             [],
  sen_learning_support:  null,
  sen_behaviour_support: null,
  instagram_url: instagramUrl,
  linkedin_url:  linkedinUrl,
  facebook_url:  facebookUrl,
  last_modified_at:      data.dateModified ?? null,
  last_scraped_at:       new Date().toISOString(),
  extraction_confidence: 0.85,
  scrape_status:         'ok'
};

return [{ json: { school, fees, entry_points: [], scrape_status: 'ok', source_url: sourceUrl, scrape_queue_id: scrapeQueueId } }];

// Supabase returns an array for upserts with return=representation.
const resp = $input.first().json;
const row = Array.isArray(resp) ? resp[0] : resp;
const schoolId = row.id;

const prev = $('Extract JSON-LD').first().json;

// Inject school_id into child rows before insert
const feesWithId        = prev.fees.map(f => ({ ...f, school_id: schoolId }));
const entryPointsWithId = prev.entry_points.map(e => ({ ...e, school_id: schoolId }));

return [{
  json: {
    school_id:       schoolId,
    fees:            feesWithId,
    entry_points:    entryPointsWithId,
    source_url:      prev.source_url,
    scrape_queue_id: prev.scrape_queue_id
  }
}];
